// Copies the curated list of ../docs pages (docs-manifest.json) into
// website/docs, so the site never drifts from the repo docs. Run by
// `prebuild`/`prestart`; the generated files are committed and CI checks that
// running this leaves the tree unchanged.
//
// Per page: the H1 becomes front matter, relative links to other listed pages
// become site links, any other repo-relative link becomes a GitHub URL.
import {readFileSync, writeFileSync, mkdirSync, existsSync, statSync} from 'node:fs';
import {dirname, join, posix, resolve, relative} from 'node:path';
import {fileURLToPath} from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const site = resolve(here, '..');
const root = resolve(site, '..');
const manifest = JSON.parse(readFileSync(join(site, 'docs-manifest.json'), 'utf8'));
const gh = `https://github.com/${manifest.repo}`;
const bySrc = new Map(manifest.pages.map((p) => [posix.normalize(p.src), p]));

for (const [dir, s] of Object.entries(manifest.sections)) {
  const d = join(site, 'docs', dir);
  mkdirSync(d, {recursive: true});
  const cat = join(d, '_category_.json');
  if (!existsSync(cat)) {
    writeFileSync(
      cat,
      JSON.stringify(
        {label: s.label, position: s.position, link: {type: 'generated-index', description: s.description}},
        null,
        2,
      ) + '\n',
    );
  }
}

function rewriteLinks(text, fromDest, srcDir) {
  let inFence = false;
  return text
    .split('\n')
    .map((line) => {
      if (/^\s*(```|~~~)/.test(line)) inFence = !inFence;
      if (inFence) return line;
      return line.replace(/\]\(([^)\s]+)\)/g, (m, target) => {
        if (/^(https?:|mailto:|#|pathname:)/.test(target)) {
          return `](${target.replace('zyvorai.github.io/netra/', 'zyvorai.github.io/zyvor-netra/')})`;
        }
        const [path, frag] = target.split('#');
        const repoPath = posix.normalize(posix.join(srcDir, path));
        const hit = bySrc.get(repoPath);
        if (hit) {
          const rel = posix.relative(posix.dirname(fromDest), hit.dest);
          return `](${rel.startsWith('.') ? rel : './' + rel}.md${frag ? '#' + frag : ''})`;
        }
        const abs = join(root, repoPath);
        const kind = existsSync(abs) && statSync(abs).isDirectory() ? 'tree' : 'blob';
        return `](${gh}/${kind}/main/${repoPath}${frag ? '#' + frag : ''})`;
      });
    })
    .join('\n');
}

for (const page of manifest.pages) {
  const srcFile = join(root, 'docs', page.src);
  if (!existsSync(srcFile)) throw new Error(`docs-manifest: missing docs/${page.src}`);
  const raw = readFileSync(srcFile, 'utf8');
  const lines = raw.split('\n');
  const h1 = lines.findIndex((l) => l.startsWith('# '));
  if (h1 < 0) throw new Error(`docs/${page.src}: no H1`);
  const title = lines[h1].slice(2).trim();
  const body = [...lines.slice(0, h1), ...lines.slice(h1 + 1)].join('\n').replace(/^\s*\n/, '');
  const srcDir = posix.dirname(posix.join('docs', page.src));
  const out = [
    '---',
    `title: ${JSON.stringify(title)}`,
    `sidebar_position: ${page.position}`,
    `custom_edit_url: ${gh}/edit/main/docs/${page.src}`,
    '---',
    '',
    `<!-- GENERATED by website/scripts/sync-docs.mjs from docs/${page.src}. Edit the source. -->`,
    '',
    rewriteLinks(body, page.dest, srcDir),
  ].join('\n');
  const dest = join(site, 'docs', `${page.dest}.md`);
  mkdirSync(dirname(dest), {recursive: true});
  writeFileSync(dest, out.endsWith('\n') ? out : out + '\n');
}
// Release notes: the most recent N sections of CHANGELOG.md, so they live in
// the site; the full history stays on GitHub.
if (manifest.changelog) {
  const cl = manifest.changelog;
  const lines = readFileSync(join(root, 'CHANGELOG.md'), 'utf8').split('\n');
  const heads = lines.flatMap((l, i) => (l.startsWith('## ') ? [i] : []));
  const end = heads[Math.min(cl.releases, heads.length - 1)] ?? lines.length;
  const body = lines.slice(heads[0], end).join('\n').trimEnd();
  const out = [
    '---',
    'title: "Changelog"',
    `sidebar_position: ${cl.position}`,
    `custom_edit_url: ${gh}/edit/main/CHANGELOG.md`,
    '---',
    '',
    '<!-- GENERATED by website/scripts/sync-docs.mjs from CHANGELOG.md. Edit the source. -->',
    '',
    `The latest ${cl.releases} entries. The full history is in [CHANGELOG.md](${gh}/blob/main/CHANGELOG.md).`,
    '',
    rewriteLinks(body, cl.dest, '.'),
    '',
  ].join('\n');
  const dest = join(site, 'docs', `${cl.dest}.md`);
  mkdirSync(dirname(dest), {recursive: true});
  writeFileSync(dest, out);
}
console.log(`sync-docs: ${manifest.pages.length} pages`);
